import{_ as t,o as r,c as o,a3 as a}from"./chunks/framework.D1iekJsc.js";const p=JSON.parse('{"title":"OpenRouter","description":"OpenRouter 免费模型：官网 Free Models 合集、:free 文本/视觉列表、拿 Key 与限额，以及在 MiniTavern 中的填法。","frontmatter":{"title":"OpenRouter","description":"OpenRouter 免费模型：官网 Free Models 合集、:free 文本/视觉列表、拿 Key 与限额，以及在 MiniTavern 中的填法。","head":[["meta",{"name":"keywords","content":"酒馆,AI酒馆,Ai酒馆,迷你酒馆,超迷你酒馆,MiniTavern,AI伙伴,AI朋友,Ai本地聊天,AI本地聊天,Silly Tavern,SillyTavern,手机玩Silly Tavern,Silly Tavern手机版,Silly Tavern安卓,Silly Tavern苹果,AI角色扮演,角色卡,角色扮演,AI聊天,手机AI,离线AI,AI剧情,本地大模型,本地模型,Ollama,LM Studio,世界书,正则,BYOK,用户手册,教程,character card,AI roleplay,AI companion,tavern AI"}],["meta",{"property":"og:title","content":"OpenRouter · MiniTavern Docs"}],["meta",{"property":"og:description","content":"OpenRouter 免费模型：官网 Free Models 合集、:free 文本/视觉列表、拿 Key 与限额，以及在 MiniTavern 中的填法。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/free-cloud/openrouter"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/free-cloud/openrouter"}]]},"headers":[],"relativePath":"free-cloud/openrouter.md","filePath":"free-cloud/openrouter.md","lastUpdated":1787217957000}'),d={name:"free-cloud/openrouter.md"};function n(i,e,l,c,s,h){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="openrouter" tabindex="-1">OpenRouter <a class="header-anchor" href="#openrouter" aria-label="Permalink to &quot;OpenRouter&quot;">​</a></h1><p>全球模型聚合网关：一个 API Key 可调用大量模型。其中部分为 <strong>免费池</strong>（模型 ID 常以 <code>:free</code> 结尾，或官方标 Free），适合个人试用、对比开源模型与低频角色扮演。官方合集：<a href="https://openrouter.ai/collections/free-models" target="_blank" rel="noreferrer">Free Models</a>；第三方汇总可参考 <a href="https://openairouter.net/free-models" target="_blank" rel="noreferrer">openairouter.net/free-models</a>（非官方，以 OpenRouter 控制台为准）。</p><blockquote><p>免费名单、RPM / 日请求上限会变。<strong>以 <a href="https://openrouter.ai/models?q=free" target="_blank" rel="noreferrer">openrouter.ai/models</a> 与账户页为准</strong>。</p></blockquote><h2 id="官网与入口" tabindex="-1">官网与入口 <a class="header-anchor" href="#官网与入口" aria-label="Permalink to &quot;官网与入口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资源</th><th>地址</th></tr></thead><tbody><tr><td>官网</td><td><a href="https://openrouter.ai/" target="_blank" rel="noreferrer">openrouter.ai</a></td></tr><tr><td>API Key</td><td><a href="https://openrouter.ai/keys" target="_blank" rel="noreferrer">openrouter.ai/keys</a></td></tr><tr><td>Free Models 合集</td><td><a href="https://openrouter.ai/collections/free-models" target="_blank" rel="noreferrer">openrouter.ai/collections/free-models</a></td></tr><tr><td>模型广场（筛 Free）</td><td><a href="https://openrouter.ai/models?q=free" target="_blank" rel="noreferrer">openrouter.ai/models?q=free</a></td></tr><tr><td>社区汇总（第三方）</td><td><a href="https://openairouter.net/free-models" target="_blank" rel="noreferrer">openairouter.net/free-models</a></td></tr><tr><td>API Base URL</td><td><code>https://openrouter.ai/api/v1</code>（MiniTavern 选 <strong>OpenRouter</strong> 时一般无需手填）</td></tr></tbody></table><h2 id="免费怎么获取" tabindex="-1">免费怎么获取 <a class="header-anchor" href="#免费怎么获取" aria-label="Permalink to &quot;免费怎么获取&quot;">​</a></h2><ol><li>打开 <a href="https://openrouter.ai/keys" target="_blank" rel="noreferrer">openrouter.ai/keys</a> 注册并创建 Key（通常 <strong>无需信用卡</strong>）。</li><li>在 <a href="https://openrouter.ai/collections/free-models" target="_blank" rel="noreferrer">Free Models</a> 或模型广场复制 <strong>Model ID</strong>（注意 <code>:free</code> 后缀）。</li><li>在 MiniTavern 选平台 <strong>OpenRouter</strong>，粘贴 Key，模型填该 ID。</li></ol><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>免费方式</td><td>ID 含 <code>:free</code>，或合集中标价 <code>$0</code> 的模型；也可用自动路由 <code>openrouter/free</code></td></tr><tr><td>限速参考</td><td>常见约 <strong>20 RPM / 约 50 次/天</strong>；一次性充值约 <strong>$10+</strong> 后，免费模型日限额可升至约 <strong>1000 次/天</strong>（规则以官方为准）</td></tr><tr><td>绑卡</td><td>免费档通常不需要；充值仅用于提高限额或调用付费模型</td></tr><tr><td>隐私</td><td>部分免费上游可能用提示词改进模型；可在 OpenRouter 设置查看隐私选项。Poolside Laguna 等免费档文档写明可能用于训练</td></tr></tbody></table><h2 id="模型列表" tabindex="-1">模型列表 <a class="header-anchor" href="#模型列表" aria-label="Permalink to &quot;模型列表&quot;">​</a></h2><p>下列为合集与公开汇总中的常见 <strong>文本 / 视觉</strong> ID（约 2026-08）；<strong>实际以官网为准</strong>。ID <strong>大小写敏感</strong>，<code>:free</code> 不可省略（除非该条目本身无此后缀）。</p><h3 id="文本-·-自动路由" tabindex="-1">文本 · 自动路由 <a class="header-anchor" href="#文本-·-自动路由" aria-label="Permalink to &quot;文本 · 自动路由&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模型 ID</th><th>说明</th></tr></thead><tbody><tr><td><code>openrouter/free</code></td><td>按请求自动挑选可用免费模型；上手最快，质量不固定</td></tr></tbody></table><h3 id="文本-·-通用对话" tabindex="-1">文本 · 通用对话 <a class="header-anchor" href="#文本-·-通用对话" aria-label="Permalink to &quot;文本 · 通用对话&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模型 ID</th><th>说明</th></tr></thead><tbody><tr><td><code>meta-llama/llama-3.3-70b-instruct:free</code></td><td>综合向、多语言</td></tr><tr><td><code>meta-llama/llama-3.2-3b-instruct:free</code></td><td>轻量</td></tr><tr><td><code>openai/gpt-oss-20b:free</code> / <code>openai/gpt-oss-120b:free</code></td><td>OpenAI 开源权重 MoE</td></tr><tr><td><code>google/gemma-3-27b-it:free</code> / <code>google/gemma-3-12b-it:free</code> / <code>google/gemma-3-4b-it:free</code></td><td>Gemma 3 系列</td></tr><tr><td><code>google/gemma-4-31b-it:free</code> / <code>google/gemma-4-26b-a4b-it:free</code></td><td>Gemma 4（部分支持视觉）</td></tr><tr><td><code>google/gemma-3n-e4b-it:free</code> / <code>google/gemma-3n-e2b-it:free</code></td><td>端侧向轻量</td></tr><tr><td><code>qwen/qwen3-next-80b-a3b-instruct:free</code></td><td>Qwen3 对话</td></tr><tr><td><code>z-ai/glm-4.5-air:free</code></td><td>GLM 轻量，中文友好</td></tr><tr><td><code>minimax/minimax-m2.5:free</code></td><td>MiniMax</td></tr><tr><td><code>nousresearch/hermes-3-llama-3.1-405b:free</code></td><td>Hermes 3</td></tr><tr><td><code>arcee-ai/trinity-large-preview:free</code></td><td>Arcee Trinity Large Preview</td></tr><tr><td><code>openrouter/elephant-alpha</code></td><td>OpenRouter 托管文本模型（合集/广场若标 Free）</td></tr><tr><td><code>cognitivecomputations/dolphin-mistral-24b-venice-edition:free</code></td><td>Venice Uncensored 变体（内容尺度自行把握）</td></tr></tbody></table><h3 id="文本-·-推理-agent-编码" tabindex="-1">文本 · 推理 / Agent / 编码 <a class="header-anchor" href="#文本-·-推理-agent-编码" aria-label="Permalink to &quot;文本 · 推理 / Agent / 编码&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模型 ID</th><th>说明</th></tr></thead><tbody><tr><td><code>qwen/qwen3-coder:free</code></td><td>Qwen3 Coder，代码向</td></tr><tr><td><code>nvidia/nemotron-3-ultra:free</code>（或合集当前 ID）</td><td>Nemotron 3 Ultra，长上下文 Agent</td></tr><tr><td><code>nvidia/nemotron-3.5-lightning:free</code></td><td>高吞吐 Agent</td></tr><tr><td><code>nvidia/nemotron-3-super-120b-a12b:free</code></td><td>Nemotron 3 Super</td></tr><tr><td><code>nvidia/nemotron-3-nano-30b-a3b:free</code> / <code>nvidia/nemotron-nano-9b-v2:free</code></td><td>Nano 系列</td></tr><tr><td><code>poolside/laguna-s-2.1:free</code> / <code>poolside/laguna-xs-2.1:free</code>（以广场 ID 为准）</td><td>Poolside 编码 Agent；免费档可能用于训练</td></tr><tr><td><code>cohere/north-mini-code:free</code>（以广场为准）</td><td>Cohere North 编码</td></tr><tr><td><code>liquid/lfm-2.5-1.2b-instruct:free</code> / <code>liquid/lfm-2.5-1.2b-thinking:free</code></td><td>Liquid 轻量</td></tr><tr><td><code>dots-studio/dots3-note-preview:free</code>（以广场为准）</td><td>Dots3-Note Preview</td></tr></tbody></table><p>合集按用量排序会变；编程向亦可在 <a href="https://openrouter.ai/collections/coding" target="_blank" rel="noreferrer">Coding</a> 中再筛 Free。</p><h3 id="文本-·-视觉-多模态输入" tabindex="-1">文本 · 视觉（多模态输入） <a class="header-anchor" href="#文本-·-视觉-多模态输入" aria-label="Permalink to &quot;文本 · 视觉（多模态输入）&quot;">​</a></h3><p>聊天主模型若支持视觉，可在 App 开启识图 / 多模态直传时试用：</p><table tabindex="0"><thead><tr><th>模型 ID</th><th>说明</th></tr></thead><tbody><tr><td><code>google/gemma-3-27b-it:free</code> 等 Gemma 3/4</td><td>文 + 图输入</td></tr><tr><td><code>nvidia/nemotron-nano-12b-v2-vl:free</code></td><td>视觉 / 文档</td></tr><tr><td><code>nvidia/nemotron-3-nano-omni:free</code>（以广场为准）</td><td>多模态感知</td></tr><tr><td><code>meta-llama/llama-guard-4-12b:free</code></td><td>安全分类向，一般不当聊天主模型</td></tr></tbody></table><h3 id="图片-视频" tabindex="-1">图片 / 视频 <a class="header-anchor" href="#图片-视频" aria-label="Permalink to &quot;图片 / 视频&quot;">​</a></h3><ul><li><strong>生图</strong>：见 OpenRouter <a href="https://openrouter.ai/collections/image-models" target="_blank" rel="noreferrer">Image Models</a>；是否免费以模型页定价为准。MiniTavern 生图连接可选 <strong>OpenRouter</strong>。</li><li><strong>视频</strong>：见 <a href="https://openrouter.ai/collections/video-models" target="_blank" rel="noreferrer">Video Models</a>；App <strong>无内置视频入口</strong>。</li><li>第三方列表中的 Lyria 等偏音乐生成，与聊天 / 生图无关，勿当对话模型。</li></ul><h2 id="在-minitavern-里怎么填" tabindex="-1">在 MiniTavern 里怎么填 <a class="header-anchor" href="#在-minitavern-里怎么填" aria-label="Permalink to &quot;在 MiniTavern 里怎么填&quot;">​</a></h2><p>通用步骤见 <a href="/ultra_guides/manual/model-link">模型连接</a>。</p><h3 id="聊天" tabindex="-1">聊天 <a class="header-anchor" href="#聊天" aria-label="Permalink to &quot;聊天&quot;">​</a></h3><p>路径：<strong>设置 → 模型 → 模型连接 → 新建</strong></p><ol><li>平台选 <strong>OpenRouter</strong>（预设 Base URL）</li><li>粘贴 API Key</li><li>模型 ID 填例如 <code>meta-llama/llama-3.3-70b-instruct:free</code>，或 <code>openrouter/free</code></li><li><strong>测试</strong> → 成功后设为默认</li></ol><p>也可选 <strong>自定义 (OpenAI)</strong>，Base URL <code>https://openrouter.ai/api/v1</code>，效果类似；优先用 App 预设。</p><h3 id="生图" tabindex="-1">生图 <a class="header-anchor" href="#生图" aria-label="Permalink to &quot;生图&quot;">​</a></h3><p>路径：<strong>设置 → 生图 → 生图连接</strong> → 平台 <strong>OpenRouter</strong>，模型选广场中支持图像且免费（或可接受计费）的 ID。更稳的免费生图见 <a href="/ultra_guides/free-cloud/agnes-ai">Agnes AI</a>、<a href="/ultra_guides/free-cloud/aihubmix">AIHubMix</a>。</p><h3 id="排错" tabindex="-1">排错 <a class="header-anchor" href="#排错" aria-label="Permalink to &quot;排错&quot;">​</a></h3><table tabindex="0"><thead><tr><th>现象</th><th>处理</th></tr></thead><tbody><tr><td><code>HTTP 429</code> / <code>Provider returned error</code></td><td>上游免费池满或限流：换其它 <code>:free</code>、稍后再试，或 <a href="https://openrouter.ai/settings/integrations" target="_blank" rel="noreferrer">BYOK</a></td></tr><tr><td>国内访问失败</td><td>官方 API 可能需代理；或改用国内直连厂商 / <a href="/ultra_guides/free-cloud/aihubmix">AIHubMix</a> 等</td></tr><tr><td>模型 404 / unavailable</td><td>该 <code>:free</code> 已下线：到合集重新复制 ID</td></tr></tbody></table><p>更多见 <a href="/ultra_guides/manual/errors">错误排错</a>。</p><h2 id="相关章节" tabindex="-1">相关章节 <a class="header-anchor" href="#相关章节" aria-label="Permalink to &quot;相关章节&quot;">​</a></h2><ul><li><a href="/ultra_guides/free-cloud/">免费云端总览</a></li><li><a href="/ultra_guides/free-cloud/freellm">FreeLLM 目录</a> — 更多免费厂商索引</li><li><a href="/ultra_guides/free-cloud/aihubmix">AIHubMix</a> — 补贴型 <code>*-free</code>（含部分闭源镜像）</li><li><a href="/ultra_guides/free-cloud/agnes-ai">Agnes AI</a> · <a href="/ultra_guides/free-cloud/opencode-zen">OpenCode Zen</a></li><li><a href="/ultra_guides/manual/model-link">模型连接</a></li><li><a href="/ultra_guides/free-cloud/#免费生图怎么配">免费生图</a></li></ul>',35)])])}const f=t(d,[["render",n]]);export{p as __pageData,f as default};
